package vn.codegym.mvc.controller;import vn.codegym.mvc.model.Customer;import vn.codegym.mvc.service.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.HttpServletRequest;
@WebServlet("/customers") public final class CustomerServlet extends CrudServlet<Customer>{private final CustomerServiceImpl service=new CustomerServiceImpl();protected MemoryService<Customer> service(){return service;}protected String kind(){return "customers";}protected String title(){return "Quản lý khách hàng";}protected Customer input(HttpServletRequest r){String name=field(r,"name",100),email=field(r,"email",100),address=field(r,"address",255);if(!email.matches("[^\\s@]+@[^\\s@]+\\.[^\\s@]+"))throw new IllegalArgumentException("Email không hợp lệ.");return new Customer(name,email,address);}}
